import jinja2

def handle(query, state):
    name = (query.get("name") or [""])[0]
    if not name:
        return 200, {"Content-Type": "text/html"}, "<html><body><form>Name: <input name=name><button>Greet</button></form></body></html>"
    try:
        greeting = jinja2.Template(name).render(state=state)
    except jinja2.TemplateSyntaxError as e:
        greeting = "(template error: {})".format(e.message)
    body = "<html><body><p>Hello, {}!</p><form>Name: <input name=name value=\"{}\"><button>Greet</button></form></body></html>".format(greeting, name.replace('"', '&quot;'))
    return 200, {"Content-Type": "text/html"}, body
